/**
 * Activepieces Code piece — Service C, Stack C2: Approved follow-up send gate.
 *
 * Runs inside the **C-send** flow (Webhook trigger). Reads the Followup-Outbox tab
 * and releases ONLY the rows a human marked `approved` and that haven't been sent.
 * Applies a throttle + test-mode redirect (same idea as Service A's stack 06), then
 * hands back: the batch to send, the rows to append to the separate Followup-Sent
 * sheet, the the CRM touch-updates, and the Outbox rows to DELETE (clean-up) — sorted
 * bottom-up so deleting one row never shifts the row number of another pending one.
 *
 * Flow:  Webhook -> Sheets Get Rows (Followup-Outbox) -> THIS
 *        -> Loop(toSend)->Gmail Send
 *        -> Loop(sentRows)->Sheets Insert Row (Followup-Sent)
 *        -> Code c3-the CRM-touch-update (touchUpdates)
 *        -> Loop(outboxDeletes)->Sheets Delete Row (Followup-Outbox).
 *
 * INPUTS
 *   outbox        = rows from the Followup-Outbox tab (must include each row's line no.)
 *   maxPerRun     = default 20
 *   dailyCap      = default 60
 *   testMode      = boolean
 *   testRecipient = your inbox (required if testMode)
 *
 * OUTPUT { toSend, sentRows, touchUpdates, outboxDeletes, skipped }
 */

export const code = async (inputs) => {
  const normSheet = (v) => {
    let rows = Array.isArray(v) ? v
      : (v && (Array.isArray(v.rows) ? v.rows
        : Array.isArray(v.values) ? v.values
        : Array.isArray(v.body) ? v.body : [])) || [];
    if (!Array.isArray(rows)) rows = [];
    rows = rows.map((r) => (r && typeof r.values === 'object' && r.values) ? { row: r.row, ...r.values } : r);
    const lettered = rows.some((r) => r && (r.A !== undefined || r.B !== undefined));
    if (!lettered) return rows;
    const header = rows.find((r) => String(r.row) === '1') || rows[0];
    if (!header) return [];
    const map = {};
    for (const [k, val] of Object.entries(header)) if (k !== 'row') map[k] = String(val).trim();
    const out = [];
    for (const r of rows) {
      if (r === header || String(r.row) === '1') continue;
      const obj = {};
      if (r.row !== undefined) obj.row = r.row;
      for (const [k, val] of Object.entries(r)) {
        if (k === 'row') continue;
        const name = map[k];
        if (name) obj[name] = val;
      }
      out.push(obj);
    }
    return out;
  };

  const outbox = normSheet(inputs.outbox);
  const maxPerRun = Number(inputs.maxPerRun) > 0 ? Number(inputs.maxPerRun) : 20;
  const dailyCap = Number(inputs.dailyCap) > 0 ? Number(inputs.dailyCap) : 60;
  const testMode = Boolean(inputs.testMode);
  const testRecipient = String(inputs.testRecipient || '').trim();

  const isApproved = (v) => /^(y|yes|true|1|approve|approved|✓|x)$/i.test(String(v || '').trim());
  const isSent = (v) => /^(sent|done)$/i.test(String(v || '').trim());

  if (testMode && !testRecipient) {
    return { toSend: [], sentRows: [], touchUpdates: [], outboxDeletes: [],
      skipped: { error: 'testMode on but no testRecipient' } };
  }

  const skipped = { notApproved: 0, alreadySent: 0, noRow: 0, noEmail: 0 };
  const eligible = [];
  for (const r of outbox) {
    if (!isApproved(r.approved)) { skipped.notApproved++; continue; }
    if (isSent(r.status)) { skipped.alreadySent++; continue; }
    if (r.row === undefined || r.row === null || r.row === '') { skipped.noRow++; continue; }
    if (!String(r.to || '').includes('@')) { skipped.noEmail++; continue; }
    eligible.push(r);
  }

  const takeN = Math.min(maxPerRun, dailyCap, eligible.length);
  const batch = eligible.slice(0, takeN);

  const nowIso = new Date().toISOString();
  const toSend = [];
  const sentRows = [];
  const touchUpdates = [];
  const outboxDeletes = [];

  for (const r of batch) {
    const realTo = r.to;
    toSend.push({
      to: testMode ? testRecipient : realTo,
      subject: testMode ? `[TEST → ${realTo}] ${r.subject}` : r.subject,
      body: r.body,
    });
    sentRows.push({
      touchNo: r.touchNo || '', contact: r.contact || '', client: r.client || '',
      country: r.country || '', to: realTo, subject: r.subject || '',
      status: 'sent', sentAt: nowIso, the CRMId: r.the CRMId || '',
      buyerKey: r.buyerKey || '', testMode: testMode ? 'yes' : 'no',
    });
    // c3 turns these into a the CRM update: bump Touch_Count, stamp Last_Touch_At.
    touchUpdates.push({
      the CRMId: r.the CRMId || '', to: realTo,
      touchNo: Number(r.touchNo || 0), lastTouchAt: nowIso,
      testMode: testMode ? 'yes' : 'no',
    });
    outboxDeletes.push({ row: Number(r.row) });
  }

  // delete bottom-up so removing one row doesn't renumber the rows still pending.
  outboxDeletes.sort((a, b) => b.row - a.row);

  return {
    toSend, sentRows, touchUpdates, outboxDeletes,
    skipped: { ...skipped, eligible: eligible.length, sending: batch.length,
      heldByThrottle: Math.max(0, eligible.length - batch.length) },
  };
};

/**
 * Activepieces Code piece — Service C, Stack C3: the CRM touch write-back.
 *
 * Runs inside the **C-send** flow, right after the follow-ups are sent. For each
 * contact just nudged it updates the the CRM Contact record so the next C-draft run
 * sees the new state: bumps the touch count and stamps the last-touch time. This is
 * what closes the loop — the CRM is Service C's source of truth, so without this the
 * same contacts would be re-drafted next run.
 *
 * In testMode nothing is written to the CRM (so a dry run leaves the CRM untouched),
 * unless writeInTestMode=true.
 *
 * Flow:  … Gmail Send -> Insert Followup-Sent -> THIS -> Loop(outboxDeletes)->Delete.
 *
 * INPUTS
 *   updates         = c2.touchUpdates  [{ the CRMId, to, touchNo, lastTouchAt, testMode }]
 *   the CRMAccessToken = {{connections['the CRM'].access_token}}   (required)
 *   apiDomain       = the CRM DC host (default https://www.the CRMapis.com)
 *   apiVersion      = default 'v2'
 *   touchCountField = default 'Touch_Count'
 *   lastTouchField  = default 'Last_Touch_At'
 *   writeInTestMode = default false (skip the CRM writes while testing)
 *
 * OUTPUT { updated, skipped, errors }
 */

export const code = async (inputs) => {
  const updates = Array.isArray(inputs.updates) ? inputs.updates : [];
  const token = String(inputs.the CRMAccessToken || '').trim();
  const apiDomain = String(inputs.apiDomain || 'https://www.the CRMapis.com').replace(/\/+$/, '');
  const apiVersion = String(inputs.apiVersion || 'v2').replace(/^\/+|\/+$/g, '');
  const F_TOUCH = String(inputs.touchCountField || 'Touch_Count');
  const F_LAST = String(inputs.lastTouchField || 'Last_Touch_At');
  const writeInTestMode = Boolean(inputs.writeInTestMode);

  if (!token) return { updated: 0, skipped: updates.length, errors: ['no the CRMAccessToken'] };

  const sleep = (ms) => new Promise((res) => setTimeout(res, ms));
  const base = `${apiDomain}/crm/${apiVersion}/Contacts`;

  let updated = 0;
  let skipped = 0;
  const errors = [];

  for (const u of updates) {
    if (!writeInTestMode && String(u.testMode) === 'yes') { skipped++; continue; }
    const id = String(u.the CRMId || '').trim();
    if (!id) { skipped++; continue; } // no the CRM id — can't target the record

    const record = {};
    record[F_TOUCH] = Number(u.touchNo || 0);
    record[F_LAST] = u.lastTouchAt || new Date().toISOString();

    try {
      const r = await fetch(`${base}/${encodeURIComponent(id)}`, {
        method: 'PUT',
        headers: {
          Authorization: 'the CRM-oauthtoken ' + token,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ data: [record] }),
        signal: AbortSignal.timeout(20000),
      });
      const body = await r.json().catch(() => ({}));
      const ok = r.ok && body && Array.isArray(body.data) &&
        body.data[0] && body.data[0].code === 'SUCCESS';
      if (ok) updated++;
      else errors.push({ id, status: r.status, detail: body && body.data && body.data[0] });
    } catch (e) {
      errors.push({ id, error: String(e && e.message) });
    }
    await sleep(120); // stay under the CRM's per-second write budget
  }

  return { updated, skipped, errors };
};
